package io.ochre.bridge;
import java.lang.instrument.Instrumentation;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
/// Creates a disposable demo world only inside the native smoke test's temporary game directory.
public final class FoundationProbeAgent {
 public static void premain(String ignored,Instrumentation instrumentation){Thread worker=new Thread(()->{try{
  var cm=BridgeAgent.class.getDeclaredMethod("client");cm.setAccessible(true);Object client=null;Path work=null;
  for(int i=0;i<1000;i++){try{client=cm.invoke(null);work=((java.io.File)client.getClass().getField("gameDirectory").get(client)).toPath();if(Files.exists(work.resolve("foundation-start")))break;}catch(Exception e){}Thread.sleep(100);}
  final Object c=client;final Path path=work;var opened=new CompletableFuture<Void>();((Executor)c).execute(()->{try{ActionSupport.field(c,"options").getClass().getField("pauseOnLostFocus").setBoolean(ActionSupport.field(c,"options"),false);Object gui=ActionSupport.field(c,"gui");gui.getClass().getMethod("setScreen",ActionSupport.type(c,"net.minecraft.client.gui.screens.Screen")).invoke(gui,ActionSupport.type(c,"net.minecraft.client.gui.screens.TitleScreen").getConstructor().newInstance());Object screen=InputActions.screen(c);List<String> labels=new ArrayList<>();for(Object child:(List<?>)ActionSupport.call(screen,"children")){try{String text=ActionSupport.call(ActionSupport.call(child,"getMessage"),"getString").toString();labels.add(text);if(text.toLowerCase(Locale.ROOT).contains("play demo")){Object event=ActionSupport.type(c,"net.minecraft.client.input.KeyEvent").getConstructor(int.class,int.class,int.class).newInstance(257,0,0);child.getClass().getMethod("onPress",ActionSupport.type(c,"net.minecraft.client.input.InputWithModifiers")).invoke(child,event);opened.complete(null);return;}}catch(NoSuchMethodException e){}}throw new AssertionError("Demo button missing: "+screen.getClass()+labels);}catch(Throwable e){opened.completeExceptionally(e);}});opened.get(15,TimeUnit.SECONDS);
  for(int i=0;i<1200;i++){var ready=new CompletableFuture<Boolean>();((Executor)c).execute(()->{try{Object p=ActionSupport.field(c,"player");if(p==null){ready.complete(false);return;}if(InputActions.screen(c)!=null)ActionSupport.field(c,"gui").getClass().getMethod("setScreen",ActionSupport.type(c,"net.minecraft.client.gui.screens.Screen")).invoke(ActionSupport.field(c,"gui"),new Object[]{null});ready.complete(true);}catch(Throwable e){ready.completeExceptionally(e);}});if(ready.get(5,TimeUnit.SECONDS)){Object server=ActionSupport.call(c,"getSingleplayerServer");var prepared=new CompletableFuture<Void>();((Executor)server).execute(()->{try{Object level=ActionSupport.call(server,"overworld");for(int cx=-1;cx<=0;cx++)for(int cz=-1;cz<=0;cz++)level.getClass().getMethod("getChunk",int.class,int.class).invoke(level,cx,cz);Object commands=ActionSupport.call(server,"getCommands"),source=ActionSupport.call(server,"createCommandSourceStack");var method=commands.getClass().getMethod("performPrefixedCommand",ActionSupport.type(c,"net.minecraft.commands.CommandSourceStack"),String.class);for(String command:List.of("gamemode creative BridgeSmoke","tp BridgeSmoke 0.5 90 0.5","fill -2 89 -2 5 89 2 minecraft:stone","setblock 2 90 0 minecraft:stone","item replace entity BridgeSmoke weapon.mainhand with minecraft:stone 64"))method.invoke(commands,source,command);prepared.complete(null);}catch(Throwable e){prepared.completeExceptionally(e);}});prepared.get(15,TimeUnit.SECONDS);
   for(int j=0;j<30;j++){var clear=new CompletableFuture<Void>();((Executor)c).execute(()->{try{Object gui=ActionSupport.field(c,"gui");if(InputActions.screen(c)!=null)gui.getClass().getMethod("setScreen",ActionSupport.type(c,"net.minecraft.client.gui.screens.Screen")).invoke(gui,new Object[]{null});clear.complete(null);}catch(Throwable e){clear.completeExceptionally(e);}});clear.get(5,TimeUnit.SECONDS);Thread.sleep(100);}
   Files.writeString(path.resolve("foundation-ready"),"ready");serve(c,path,server);return;}Thread.sleep(100);}
  throw new AssertionError("Temporary world never opened");
 }catch(Throwable e){e.printStackTrace();try{Files.writeString(Path.of(System.getProperty("user.dir")).resolve("foundation-error"),e.toString());}catch(Exception ignoredAgain){}}},"foundation probe");worker.setDaemon(true);worker.start();}
 /// Executes test-fixture requests only in the disposable game directory; this agent is never shipped.
 private static void serve(Object c,Path path,Object server)throws Exception {
  while(true){Path input=path.resolve("fixture-request");if(!Files.exists(input)){Thread.sleep(50);continue;}List<String> lines=Files.readAllLines(input);Files.delete(input);var done=new CompletableFuture<Void>();((Executor)server).execute(()->{try{Object commands=ActionSupport.call(server,"getCommands"),source=ActionSupport.call(server,"createCommandSourceStack");var method=commands.getClass().getMethod("performPrefixedCommand",ActionSupport.type(c,"net.minecraft.commands.CommandSourceStack"),String.class);for(String command:lines)if(!command.startsWith("$"))method.invoke(commands,source,command);done.complete(null);}catch(Throwable error){done.completeExceptionally(error);}});done.get(10,TimeUnit.SECONDS);Thread.sleep(500);
   if(lines.contains("$consume")){var used=new CompletableFuture<Void>();((Executor)c).execute(()->{try{Object p=ActionSupport.field(c,"player");Class<?> hand=ActionSupport.type(c,"net.minecraft.world.InteractionHand");p.getClass().getMethod("startUsingItem",hand).invoke(p,hand.getField("MAIN_HAND").get(null));var complete=ActionSupport.type(c,"net.minecraft.world.entity.LivingEntity").getDeclaredMethod("completeUsingItem");complete.setAccessible(true);complete.invoke(p);used.complete(null);}catch(Throwable error){used.completeExceptionally(error);}});used.get(5,TimeUnit.SECONDS);}
   if(lines.contains("$fov_probe")){var checked=new CompletableFuture<Void>();((Executor)c).execute(()->{try{Class<?> overlay=GameOverlay.class;var adjust=overlay.getDeclaredMethod("adjust",Object.class,boolean.class);adjust.setAccessible(true);for(String name:List.of("quick","slider","x","width","mx")){var f=overlay.getDeclaredField(name);f.setAccessible(true);if(name.equals("quick"))f.setBoolean(null,true);else if(name.equals("slider"))f.setInt(null,0);else f.setDouble(null,name.equals("width")?280d:name.equals("x")?4d:16d);}for(double ratio:new double[]{.0131,.2371,.5143,.8735}){var mx=overlay.getDeclaredField("mx");mx.setAccessible(true);mx.setDouble(null,16+110*ratio);adjust.invoke(null,c,true);var values=overlay.getDeclaredField("values");values.setAccessible(true);double value=((double[])values.get(null))[0];if(Math.abs(value-GameOverlay.expectedOption("fov",ratio*2-1))>.0001)throw new AssertionError("FOV readback did not use rounded angle: "+value);var failed=overlay.getDeclaredField("failed");failed.setAccessible(true);if(failed.getBoolean(null))throw new AssertionError("FOV disabled overlay");}var rejected=overlay.getDeclaredMethod("optionFailure",Exception.class);rejected.setAccessible(true);rejected.invoke(null,new java.io.IOException("fixture rejected setting"));var failed=overlay.getDeclaredField("failed");failed.setAccessible(true);if(failed.getBoolean(null))throw new AssertionError("Recoverable setting error disabled overlay");adjust.invoke(null,c,true);var quick=overlay.getDeclaredField("quick");quick.setAccessible(true);quick.setBoolean(null,false);var slider=overlay.getDeclaredField("slider");slider.setAccessible(true);slider.setInt(null,-1);checked.complete(null);}catch(Throwable error){checked.completeExceptionally(error);}});checked.get(10,TimeUnit.SECONDS);}
   Files.writeString(path.resolve("fixture-result"),"done");
  }
 }
}
